    auto routes=JSON::toString(projectToJson(project));chooseRouting(false);perform(routeDestination,5);check(JSON::toString(projectToJson(project))==routes&&Component::getCurrentlyModalComponent()==nullptr,"Master selection cannot open or apply a source routing change");
    auto slot=std::find_if(hits.begin(),hits.end(),[](const Hit& h){return h.pane==mixerPane&&h.action==masterInsertsOpen&&h.data==0;});if(slot!=hits.end()){auto click=event(slot->rect.getCentre());mouseDown(click);mouseUp(click);}check(masterInsertView&&!masterEffectsView&&selectedEffect==0&&selectedTrack==7,"clicking the Master EQ slot opens its editor without changing the source channel");
    auto source=JSON::toString(projectToJson(project)["tracks"]);draw();auto toggle=std::find_if(hits.begin(),hits.end(),[](const Hit& h){return h.pane==effectsPane&&h.action==effectToggle;});if(toggle!=hits.end()){auto click=event(toggle->rect.getCentre());mouseDown(click);mouseUp(click);}check(project.masterMixer.eq&&!project.tracks[7].mixer.eq&&undoStack.size()==1,"actual Master enable button edits only the Master as one Undo");perform(undoAction);check(!project.masterMixer.eq,"Master insert bypass Undo restores its prior state");perform(redoAction);check(project.masterMixer.eq,"Master insert bypass Redo restores the effect");
