    perform(analyzerChannel);perform(analyzerBack);draw();auto analyzer=std::find_if(hits.begin(),hits.end(),[](const Hit& h){return h.pane==effectsPane&&h.action==analyzerMaster;});if(analyzer!=hits.end()){auto click=event(analyzer->rect.getCentre());mouseDown(click);mouseUp(click);}check(analyzerView&&!analyzerFollowTrack,"Master stereo Analyzer selects the Master even after channel analysis was previously selected");perform(analyzerBack);
    perform(masterInsertsOpen,2);auto stereo=project.masterMixer.stereo;check(applyEffectChain(factoryEffectChains()[4],-1)&&project.masterMixer.chorus.enabled&&project.masterMixer.reverb&&project.masterMixer.stereo==stereo&&effectTarget()==-1,"Master factory-chain recall preserves its stereo utility and target");check(moveEffect(2,-6)&&project.masterMixer.order[0]==2,"Master insert reorder updates the independent processing order");auto order=project.masterMixer.order;perform(undoAction);check(project.masterMixer.order!=order,"Master reorder is undoable");perform(redoAction);
