    auto preset=captureEffectChain("Master fixture",project.masterMixer);auto chainFile=folder.getChildFile("master-inserts.pulseeffects");EffectChainPreset loaded;check(saveEffectChain(preset,chainFile).wasOk()&&loadEffectChain(chainFile,loaded).wasOk()&&applyEffectChain(loaded,-1),"Master chains use the existing checked local preset file format");
    auto rev=revision;auto frozen=masterState(project.masterMixer);perform(effectsOpen,0);check(!invokeEffectChainMenu(100+5,0,-1,rev)&&masterState(project.masterMixer)==frozen,"a stale Master chain menu cannot apply after switching to a channel without a project edit");perform(masterInsertsOpen,0);rev=revision;check(invokeEffectChainMenu(1,3,-1,rev)&&effectTarget()==-1&&selectedEffect==3,"Open effect from a Master slot menu retains the Master target");
