    frozen=JSON::toString(projectToJson(project));recording=true;perform(effectToggle,0);setParameter(eqLow,-1,.9f);setParameter(chorusMix,-1,.9f);setParameter(stereoTrim,-1,.9f);check(JSON::toString(projectToJson(project))==frozen,"recording locks Master effect switches and typed/drag parameter paths");recording=false;setParameter(chorusRate,-1,std::numeric_limits<float>::quiet_NaN());check(JSON::toString(projectToJson(project))==frozen,"nonfinite Master editor values preserve the project");
    rev=revision;setParameter(eqLow,-2,.9f);setParameter(chorusMix,-2,.9f);setParameter(stereoTrim,-2,.9f);check(revision==rev&&JSON::toString(projectToJson(project))==frozen&&parameterValue(eqLow,-2)==0,"only the explicit minus-one Master target is accepted by parameter controls");
