void Studio::runMasterInsertTransportTick(){
    auto put=[&](const char* name,bool value){transportResults.getDynamicObject()->setProperty(name,value);};
    auto accept=[&](const String& text,int result=1){if(auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent())){if(auto* editor=dialog->getTextEditor("value"))editor->setText(text);dialog->exitModalState(result);return true;}return false;};
    if(transportTicks==4600){perform(stop);cancelNoteTool(false);project=emptyProject();project.bpm=120;project.loop=true;project.patterns[0].length=4;selectedTrack=7;currentFile={};lane()={{0,4,60,.8f}};project.tracks[7].send=0;undoStack.clear();redoStack.clear();publish();perform(masterInsertsOpen,0);perform(effectToggle,0);setParameter(eqLow,-1,.65f);put("nativeMasterInsertsTarget",effectTarget()==-1&&project.masterMixer.eq&&!project.tracks[7].mixer.eq);}
    if(transportTicks==4610){perform(masterInsertsOpen,3);perform(effectToggle,3);editChorusValue(1);put("nativeMasterInsertsDialog",accept("0.3"));}
    if(transportTicks==4615){put("nativeMasterInsertsChorus",project.masterMixer.chorus.rate==.3f&&project.tracks[7].mixer.chorus.rate==.8f);editChorusValue(4);accept("-25");}
    if(transportTicks==4620){put("nativeMasterInsertsSigned",project.masterMixer.chorus.feedback==-.25f);editModulationValue(ModulationKind::flanger,3);accept("4.5");}
    if(transportTicks==4625){put("nativeMasterInsertsFlanger",project.masterMixer.flanger.centre==4.5f);editModulationValue(ModulationKind::phaser,1);accept("0.7");}
    if(transportTicks==4630){put("nativeMasterInsertsPhaser",project.masterMixer.phaser.rate==.7f);perform(masterStereoOpen);editStereoValue(0);accept("150");}
    if(transportTicks==4635){put("nativeMasterInsertsWidth",project.masterMixer.stereo.width==1.5f&&project.tracks[7].mixer.stereo.width==1);editStereoValue(1);accept("-3.5");}
    if(transportTicks==4640){put("nativeMasterInsertsTrim",project.masterMixer.stereo.trim==-3.5f);perform(stereoEnable);editChorusValue(1);perform(effectsOpen,3);accept("2.2");}
    if(transportTicks==4645){put("nativeMasterInsertsStale",project.masterMixer.chorus.rate==.3f&&project.tracks[7].mixer.chorus.rate==.8f&&status.startsWith("Channel changed"));perform(masterInsertsOpen,4);editModulationValue(ModulationKind::flanger,3);accept("nan");}
    if(transportTicks==4650){put("nativeMasterInsertsInvalid",project.masterMixer.flanger.centre==4.5f&&status.startsWith("Enter a finite"));editStereoValue(0);perform(effectsOpen,0);accept("200");}
    if(transportTicks==4655){put("nativeMasterInsertsStereoStale",project.masterMixer.stereo.width==1.5f&&project.tracks[7].mixer.stereo.width==1);perform(masterInsertsOpen,3);editChorusValue(1);accept("3.2",0);}
    if(transportTicks==4660){put("nativeMasterInsertsCancel",project.masterMixer.chorus.rate==.3f);perform(masterInsertsOpen,1);perform(effectToggle,1);setParameter(compThreshold,-1,.25f);setParameter(compRatio,-1,.3f);setParameter(compAttack,-1,.01f);engine->observedPeak.store(0);engine->start();}
    if(transportTicks==4680){put("nativeMasterInsertsAudio",engine->playing.load()&&engine->observedPeak.load()>.001f&&engine->masterGainReduction.load()>0&&engine->gainReduction[7].load()==0);put("nativeMasterInsertsOrder",moveEffect(2,-6)&&project.masterMixer.order[0]==2&&engine->playing.load());put("nativeMasterInsertsFactory",applyEffectChain(factoryEffectChains()[4],-1)&&project.masterMixer.reverb&&project.masterMixer.stereo.width==1.5f);}
    if(transportTicks==4690){auto file=transportReport.getSiblingFile("native-master-inserts.pulse");Project read;put("nativeMasterInsertsSave",saveProject(project,file).wasOk()&&loadProject(file,read).wasOk()&&masterState(read.masterMixer)==masterState(project.masterMixer));auto original=masterState(project.masterMixer);perform(masterDry);put("nativeMasterInsertsDry",!project.masterMixer.reverb&&!project.masterMixer.chorus.enabled&&!project.masterMixer.stereo.enabled&&project.delayReturn==0);perform(undoAction);put("nativeMasterInsertsUndo",masterState(project.masterMixer)==original);editChorusValue(1);recording=true;accept("3.5");}
    if(transportTicks==4695){recording=false;put("nativeMasterInsertsRecording",project.masterMixer.chorus.rate==.2f&&status.startsWith("Channel changed"));perform(stop);}
    if(transportTicks==4700){engine->observedPeak.store(0);transportFrames=engine->processedFrames.load();}
    if(transportTicks==4710)put("nativeMasterInsertsStop",engine->observedPeak.load()==0&&!engine->playing.load()&&engine->processedFrames.load()>transportFrames);
}
